#!/usr/bin/env python3
"""V3-only development artifact retention. Never operates Docker resources."""
import argparse, fcntl, hashlib, json, os, pathlib, re, shutil, subprocess, time
ROOT = pathlib.Path("/home/ar/webagent-dev3/build-jobs")
PIN = "4f605f3b-4444-4447-a511-3a9d4b9677df"
AGE = 7200
DONE = {"completed", "cancelled"}
def load(path):
    return json.loads(path.read_text())
def fingerprint(root):
    paths = [root/"coordination/items.json", *sorted(root.glob("*.json"))]
    return [(str(p), hashlib.sha256(p.read_bytes()).hexdigest()) for p in paths]
def compiler_active():
    rows = subprocess.check_output(["ps", "-eo", "comm="], text=True).splitlines()
    if any(x.strip() in {"cargo","rustc","rustdoc","buildx"} for x in rows):
        return True
    names = subprocess.check_output(["docker","ps","--format","{{.Names}}"],text=True).splitlines()
    if any(re.search(r"(?:v3|codex).*(?:build|check|perf|acceptance|test)", n) for n in names):
        return True
    return False
def plan(root, items, jobs, mounts, now):
    protected = [pathlib.Path(m).resolve() for m in mounts]
    def blocked(path):
        p=path.resolve()
        return path.is_symlink() or any(p==m or p in m.parents or m in p.parents for m in protected)
    def old(path):
        return path.exists() and now-path.stat().st_mtime >= AGE
    def terminal(t):
        j=jobs.get(t.get("job_id"), {})
        return t.get("job_id") != PIN and (t.get("status")=="abandoned" or
            t.get("status")=="closed" and j.get("status") in DONE)
    out=[]
    for key,t in items.items():
        if not re.fullmatch(r"[0-9a-f]{64}",key) or not terminal(t): continue
        finished = t.get("finished_at", jobs.get(t.get("job_id"), {}).get("finished_at", 0))
        if now - finished < AGE: continue
        for path in [root/"coordination/trees"/key,root/"checks"/key]:
            if old(path) and not blocked(path):out.append(path)
    # Keep two newest successful release jobs, as well as all mounted paths.
    completed=sorted((j for j in jobs.values() if j.get("status")=="completed"),key=lambda j:j.get("created_at",0),reverse=True)
    recent={j["job_id"] for j in completed[:2]}
    for key,j in jobs.items():
        path=root/key
        if key==PIN or key in recent or j.get("status") not in DONE or now-j.get("finished_at",0)<AGE:continue
        if old(path) and not blocked(path):out.append(path)
    # Preserve current UI selection and two newest immutable asset releases.
    assets=root/"ui-assets/releases"
    if assets.exists():
        folders=sorted((p for p in assets.iterdir() if p.is_dir() and not p.is_symlink()),key=lambda p:p.stat().st_mtime,reverse=True)
        for path in folders[2:]:
            j=jobs.get(path.name,{})
            if j.get("status")=="completed" and old(path) and not blocked(path):out.append(path)
    return out
def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument("--apply",action="store_true");args=ap.parse_args()
    with (ROOT/".v3-prune.lock").open("a") as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        if compiler_active():print("deferred: compiler or development build process active");return
        before=fingerprint(ROOT);items=load(ROOT/"coordination/items.json")
        jobs={p.stem:load(p) for p in ROOT.glob("*.json")}
        if any(j.get("status") in {"queued","running","needs_decision"} for j in jobs.values()):
            print("deferred: queued, active or decision-waiting build");return
        containers=json.loads(subprocess.check_output(["docker","inspect","webagent-dev-v3","webagent-dev-v3-loop","webagent-dev-v3-gate"],text=True))
        if any(c["State"].get("Health",{}).get("Status")!="healthy" for c in containers):raise RuntimeError("v3 runtime must be healthy")
        mounts=[m["Source"] for c in containers for m in c["Mounts"] if m["Source"].startswith(str(ROOT))]
        current=ROOT/"ui-assets/current"
        if current.exists():mounts.append(str(current.resolve()))
        # Broad /live-checkout mount is intentionally not a blanket artifact pin.
        candidates=plan(ROOT,items,jobs,mounts,time.time())
        total=0;removed=[]
        for path in candidates:
            size=int(subprocess.check_output(["du","-sk",str(path)],text=True).split()[0])*1024
            if args.apply:
                if before!=fingerprint(ROOT) or compiler_active():raise RuntimeError("inputs or compiler state changed; cleanup stopped")
                shutil.rmtree(path)
            total+=size;removed.append({"path":str(path),"bytes":size})
        report={"applied":args.apply,"count":len(removed),"GiB":round(total/1024**3,3),"artifacts":removed,"preserved_job":PIN}
        print(json.dumps({k:v for k,v in report.items() if k!="artifacts"}))
        if args.apply:
            folder=ROOT/"operator-pruning";folder.mkdir(exist_ok=True)
            (folder/(time.strftime("%Y%m%dT%H%M%SZ",time.gmtime())+".json")).write_text(json.dumps(report,indent=2)+"\n")
if __name__=="__main__":main()

#!/usr/bin/python3 -I
"""Stable root-owned timer entrypoint; resolve only the installed development guard."""
import json,os,re,stat
from pathlib import Path
def main():
    """Never execute checkout code or accept caller-controlled cleanup paths."""
    if os.geteuid()!=0:raise PermissionError("Root guard required")
    config=Path("/etc/webagent/development/build-service.json")
    cursor=config
    while cursor!=cursor.parent:
        s=cursor.lstat()
        if stat.S_ISLNK(s.st_mode)or s.st_uid!=0 or s.st_mode&0o022:raise PermissionError("Protected config path required")
        cursor=cursor.parent
    value=json.loads(config.read_bytes());directory=value.get("service_dir","")
    if not re.fullmatch(r"/var/lib/webagent/development/build-service/releases/[a-f0-9]{64}",directory):raise PermissionError("Fixed development installation required")
    if not value.get("scheduler",{}).get("task_aware_cleanup",False):
        print(json.dumps({"applied":False,"deferred":"Task-aware cleanup is disabled"}));return
    target=Path(directory)/"docker_retention.py"
    if not target.exists()and not target.is_symlink():
        print(json.dumps({"applied":False,"deferred":"Coordinated V3 retention not installed; unknown and required artifacts preserved"}))
        return
    cursor=target
    while cursor!=cursor.parent:
        s=cursor.lstat()
        if stat.S_ISLNK(s.st_mode)or s.st_uid!=0 or s.st_mode&0o022:raise PermissionError("Protected guard path required")
        cursor=cursor.parent
    os.execv("/usr/bin/python3",["python3","-I",str(target),"--apply"])
if __name__=="__main__":main()

