classes = '''class PasswordModal(Screen):
    """Masked password prompt for a secured network."""

    CSS = """
    #pw_title { height: 1; background: #003333; color: #9fd8d8; }
    Input { width: 40; margin: 1 0; }
    """

    def __init__(self, ssid: str):
        super().__init__()
        self.ssid = ssid

    def compose(self) -> ComposeResult:
        yield Static(f" Password for {self.ssid} ", id="pw_title")
        yield Input(password=True, id="pw")
        with Horizontal():
            yield Button("Connect", id="pw-ok")
            yield Button("Cancel", id="pw-cancel")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "pw-ok":
            self.dismiss((self.ssid, self.query_one("#pw", Input).value))
        elif event.button.id == "pw-cancel":
            self.dismiss(None)

    def on_input_submitted(self, event) -> None:
        self.dismiss((self.ssid, event.value))


class NetworkScreen(Screen):
    """Wi-Fi and Ethernet control surface, pushed from the boot screen."""

    BINDINGS = [
        Binding("escape", "back", "back", show=False),
        Binding("q", "back", "back", show=False),
        Binding("w", "wifi_mode", "wifi", show=False),
        Binding("e", "eth_mode", "ethernet", show=False),
        Binding("r", "refresh", "rescan", show=False),
        Binding("d", "disconnect", "disconnect", show=False),
        Binding("f", "forget", "forget", show=False),
        Binding("o", "radio", "radio", show=False),
    ]

    CSS = """
    #net_title { height: 1; background: #003333; color: #9fd8d8; }
    #net_status { height: 3; color: #b0b0b0; }
    #net_list { height: 1fr; }
    #net_hint { height: 1; color: #6b6b6b; }
    ListItem { padding: 0 0; }
    """

    def __init__(self, netio: NetIO):
        super().__init__()
        self.netio = netio
        self.mode = "wifi"      # "wifi" | "eth"
        self.items: list[dict] = []
        self.status_data: dict = {}
        self.wifi_on = True
        self.conn = "unknown"
        self.wifi_ip = ""
        self.msg = ""

    def compose(self) -> ComposeResult:
        yield Static(" Network ", id="net_title")
        yield Static("", id="net_status")
        yield ListView(id="net_list")
        yield Static(" w wifi  e ethernet  enter connect  r rescan  "
                     "d disconnect  f forget  o radio  q back", id="net_hint")

    def on_mount(self) -> None:
        self.set_interval(self._auto, 8.0)
        asyncio.create_task(self._refresh())
        self.query_one("#net_list", ListView).focus()

    # ---- data --------------------------------------------------------
    def _load_all(self) -> None:
        self.status_data = self.netio.status()
        self.wifi_on = bool(self.status_data.get("wifi_on"))
        self.conn = self.status_data.get("connectivity", "unknown")
        self.wifi_ip = ""
        if self.mode == "wifi":
            self.items = self.netio.wifi_list()
            dev = self.netio.wifi_device()
            if dev:
                self.wifi_ip = self.netio.device_ip(dev)
        else:
            self.items = self.netio.ethernet_devices()

    # ---- rendering ---------------------------------------------------
    def _item_text(self, it: dict) -> Text:
        if self.mode == "wifi":
            sig = int(it.get("signal", 0))
            color = "green" if sig >= 60 else ("yellow" if sig >= 30 else "red")
            mark = " * " if it.get("active") else "   "
            sec = it.get("security") or "open"
            t = Text(f"{mark}{it.get('ssid', '?'):24s}  {sig:3d}%  {sec}")
            t.stylize(color)
            if it.get("active"):
                t.stylize("bold")
            return t
        else:
            state = it.get("state", "?")
            color = "green" if state == "connected" else "grey62"
            t = Text(f"   {it.get('device', '?'):10s}  {state:12s}  "
                     f"{it.get('ip') or '-':15s}  {it.get('connection', '')}")
            t.stylize(color)
            return t

    def _status_text(self) -> str:
        head = f"{'WIFI' if self.mode == 'wifi' else 'ETHERNET'}   "
        head += f"internet {self.conn}"
        if self.mode == "wifi":
            head += f"   radio {'on' if self.wifi_on else 'off'}"
        lines = [head]
        if self.mode == "wifi":
            active = next((x for x in self.items if x.get("active")), None)
            if active:
                sec = active.get("security") or "open"
                lines.append(f"connected: {active['ssid']}  {active['signal']}%  {sec}  {self.wifi_ip}")
            else:
                lines.append("not connected")
        else:
            for d in self.items:
                lines.append(f"{d['device']}  {d['state']}  {d.get('ip') or '-'}")
        if self.msg:
            lines.append(f"  {self.msg}")
        return "\n".join(lines)

    def _update_status(self) -> None:
        self.query_one("#net_status", Static).update(self._status_text())

    def _render(self) -> None:
        self._update_status()
        lv = self.query_one("#net_list", ListView)
        lv.clear()
        for it in self.items:
            lv.append(ListItem(self._item_text(it)))

    # ---- refresh / modes --------------------------------------------
    async def _refresh(self) -> None:
        await asyncio.to_thread(self._load_all)
        self._render()

    async def _auto(self) -> None:
        await asyncio.to_thread(self._load_all)
        self._update_status()

    def action_refresh(self) -> None:
        asyncio.create_task(self._refresh())

    def action_wifi_mode(self) -> None:
        self.mode = "wifi"
        self.msg = "showing wifi networks"
        asyncio.create_task(self._refresh())

    def action_eth_mode(self) -> None:
        self.mode = "eth"
        self.msg = "showing ethernet devices"
        asyncio.create_task(self._refresh())

    def action_back(self) -> None:
        self.app.pop_screen()

    # ---- actions -----------------------------------------------------
    def on_list_view_selected(self, event) -> None:
        asyncio.create_task(self._connect())

    async def _connect(self) -> None:
        i = self.query_one("#net_list", ListView).index
        if i is None or i >= len(self.items):
            return
        it = self.items[i]
        if self.mode == "eth":
            up = it.get("state") != "connected"
            ok, msg = await asyncio.to_thread(self.netio.ethernet_set, it["device"], up)
        else:
            if it.get("security"):
                res = await self.app.push_screen(PasswordModal(it["ssid"]))
                if not res:
                    return
                ssid, pw = res
                ok, msg = await asyncio.to_thread(self.netio.wifi_connect, ssid, pw)
            else:
                ok, msg = await asyncio.to_thread(self.netio.wifi_connect, it["ssid"], None)
        self.msg = msg
        await self._refresh()

    def action_disconnect(self) -> None:
        asyncio.create_task(self._disconnect())

    async def _disconnect(self) -> None:
        if self.mode == "wifi":
            ok, msg = await asyncio.to_thread(self.netio.wifi_disconnect)
        else:
            i = self.query_one("#net_list", ListView).index
            if i is None or i >= len(self.items):
                return
            ok, msg = await asyncio.to_thread(self.netio.ethernet_set, self.items[i]["device"], False)
        self.msg = msg
        await self._refresh()

    def action_forget(self) -> None:
        asyncio.create_task(self._forget())

    async def _forget(self) -> None:
        if self.mode != "wifi":
            return
        i = self.query_one("#net_list", ListView).index
        if i is None or i >= len(self.items):
            return
        ssid = self.items[i]["ssid"]
        ok, msg = await asyncio.to_thread(self.netio.wifi_forget, ssid)
        self.msg = msg
        await self._refresh()

    def action_radio(self) -> None:
        asyncio.c

#!/usr/bin/env python
"""app.py - WebAgent boot dashboard (bare-bones Textual console UI).

Boot behaviour: opens on the physical console, immediately starts the
production and development stacks, then supervises them. The screen keeps
running until the user leaves into a command prompt, Chromium or XFCE.
"""
from __future__ import annotations

import asyncio
import os
import sys
import time

from textual import events
from textual.app import App, ComposeResult
from textual.binding import Binding
from textual.containers import Horizontal, Vertical
from textual.screen import Screen
from textual.widgets import Button, Input, ListItem, ListView, Static
from rich.text import Text

from services import SERVICES, SERVICE_BY_ID
from controller import Controller
from dockerio import Executor
from netio import NetIO
from netscreen import NetworkScreen
from screensaver import ScreensaverScreen

SEV_COLOR = {0: "green", 1: "yellow", 2: "red", 3: "grey62"}
EXIT_CONSOLE = 0
EXIT_CHROMIUM = 20
EXIT_XFCE = 21

# The interface rows below the four service rows (numbers 5..9), reachable
# with up/down or a number key. Each entry is (key, label, action): action
# runs on Enter/press when the row is selected; None means status-only.
EXTRAS = [
    ("net", "Network", "action_open_network"),
    ("tailscale", "Tailscale", None),
    ("console", "Command prompt", "action_leave_console"),
    ("xfce", "XFCE", "action_leave_xfce"),
    ("chromium", "Chromium", "action_leave_chromium"),
]


class ServiceRow(Horizontal):
    """One service: label + status + toggle/restart buttons."""

    def __init__(self, spec, *args, **kwargs):
        self.spec = spec
        super().__init__(id=f"row-{spec.id}", classes="row", *args, **kwargs)

    def compose(self) -> ComposeResult:
        yield Static("", id=f"sname-{self.spec.id}", classes="sname")
        yield Static("", id=f"sstatus-{self.spec.id}", classes="sstatus")
        tg = Button("Stop", id=f"tg-{self.spec.id}")
        tg.can_focus = False
        yield tg
        rs = Button("Restart", id=f"rs-{self.spec.id}")
        rs.can_focus = False
        yield rs


class ExtraRow(Horizontal):
    """One interface row below the services (Network / Tailscale / leave
    actions): left label plus a live coloured status on the right, in the
    same two-column layout as the service rows."""

    def __init__(self, index, *args, **kwargs):
        self.index = index
        super().__init__(id=f"er-{index}", classes="row", *args, **kwargs)

    def compose(self) -> ComposeResult:
        yield Static("", id=f"ename-{self.index}", classes="sname")
        yield Static("", id=f"estat-{self.index}", classes="sstatus")


class LeaveRow(Horizontal):
    """Bottom row of interface buttons."""

    def compose(self) -> ComposeResult:
        yield Button("Command prompt", id="leave-console")
        yield Button("Network", id="leave-network")
        yield Button("Chromium", id="leave-chromium")
        yield Button("XFCE", id="leave-xfce")


class BootApp(App):
    TITLE = "WebAgent server"
    SUB_TITLE = "boot console"

    CSS = """
    Screen { background: #000000; }
    #titlebar { height: 1; background: #003333; color: #9fd8d8; }
    #feed { height: 3; color: #b0b0b0; }
    .row { height: 1; }
    .sname { width: 29; }
    .sstatus { width: 30; }
    .row Button { width: 9; margin: 0 1 0 0; }
    #leave { height: 1; }
    #leave Button { width: 18; margin: 0 1 0 0; }
    #hint { height: 1; color: #6b6b6b; }
    Button { background: #0f2a3d; color: #cfe8ff; }
    Button:focus { background: #1b4a6b; }
    """

    BINDINGS = [
        Binding("s", "start_selected", "start", show=False),
        Binding("x", "stop_selected", "stop", show=False),
        Binding("r", "restart_selected", "restart", show=False),
        Binding("space", "activate_selected", "activate", show=False),
        Binding("enter", "activate_selected", "activate", show=False),
        Binding("up", "up", "up", show=False),
        Binding("down", "down", "down", show=False),
        Binding("1", "pick_1", "", show=False),
        Binding("2", "pick_2", "", show=False),
        Binding("3", "pick_3", "", show=False),
        Binding("4", "pick_4", "", show=False),
        Binding("5", "pick_5", "", show=False),
        Binding("6", "pick_6", "", show=False),
        Binding("7", "pick_7", "", show=False),
        Binding("8", "pick_8", "", show=False),
        Binding("9", "pick_9", "", show=False),
        Binding("ctrl+u", "preview_screensaver", "screensaver", show=False),
    ]

    def __init__(
        self,
        controller: Controller | None = None,
        netio: NetIO | None = None,
        saver_idle_seconds: float | None = None,
    ):
        from idle_driver import IdleLinuxDriver
        super().__init__(driver_class=IdleLinuxDriver)
        if controller is None:
            dry = bool(os.environ.get("WEBAGENT_BOOT_DRYRUN"))
            from boot_client import Controller as HostClient
            controller = HostClient(dry_run=dry)
        self.controller = controller
        self.services = getattr(controller, "services", SERVICES)
        self.service_by_id = {spec.id: spec for spec in self.services}
        self.netio = netio or NetIO(dry_run=bool(os.environ.get("WEBAGENT_BOOT_DRYRUN")))
        self.selected = 0
        self.exit_code = EXIT_CONSOLE
        self._task: asyncio.Task | None = None
        self.view: dict[str, str] = {}   # sid -> status text (for tests)
        # idle screensaver (default 60 s; 0 disables, env overrides)
        if saver_idle_seconds is None:
            try:
                saver_idle_seconds = float(
                    os.environ.get("WEBAGENT_BOOT_SAVER_SECONDS", "60")
                )
            except ValueError:
                saver_idle_seconds = 60.0
        self.saver_idle = max(0.0, float(saver_idle_seconds))
        self.saver_watch_s = 0.5
        self._idle_wake = asyncio.Event()
        self._presentation_timers = []
        self._saver: ScreensaverScreen | None = None
        self._saver_task: asyncio.Task | None = None
        self._last_activity = time.monotonic()
        self.last_net = ""

    def compose(self) -> ComposeResult:
        yield Static(" WebAgent server - boot console ", id="titlebar")
        yield Static("", id="feed")
        for spec in self.services:
            yield ServiceRow(spec)
        for i in range(len(EXTRAS)):
            yield ExtraRow(i)
        yield Static(f"  1-{len(self.services) + len(EXTRAS)} run   up/down select   enter run   s start   x stop   r restart", id="hint")

    # ------------------------------------------------------------------
    def on_mount(self) -> None:
        self._task = asyncio.create_task(self._supervise())
        if self.saver_idle > 0:
            self._saver_task = asyncio.create_task(self._watch_screensaver())

    def on_unmount(self) -> None:
        if self._task:
            self._task.cancel()
        if self._saver_task:
            self._saver_task.cancel()

    async def _supervise(self) -> None:
        while True:
            # Host recovery runs independently. Presentation sleeps until a key wakes it.
            if getattr(self.controller, "passive", False) and self.is_screensaver_up():
                await self._idle_wake.wait()
            try:
                await self.tick_once()
            except asyncio.CancelledError:
                return
            except Exception as e:  # keep the UI alive no matter what
                self.controller.push(f"dashboard error: {e}")
                await self.refresh_ui()
            await asyncio.sleep(max(1.0, self.controller.tick_s))

    async def tick_once(self) -> None:
        await asyncio.to_thread(self.controller.run_tick)
        await self.refresh_ui()

    async def refresh_ui(self) -> None:
        # Supervision still ticks; sleeping presentation performs no widget updates.
        if self.is_screensaver_up():
            return
        ctl = self.controller
        for i, spec in enumerate(self.services):
            st = ctl.statuses.get(spec.id)
            sev = st.severity if st else 3
            text = st.text if st else "?"
            rt = ctl.rt[spec.id]
            o = ctl.obs.get(spec.id)

            if o and spec.role == "app" and o.exists and o.running and not o.http_ok and o.http_text:
                text = f"{text} ({o.http_text})"

            mark = ">" if i == self.selected else " "
            plain_name = f"  {mark} {i+1} {spec.title}"
            self.view[f"{spec.id} name"] = plain_name
            name = Text(plain_name)
            if i == self.selected:
                name.stylize("bold")
            self.query_one(f"#sname-{spec.id}", Static).update(name)
            chip = "ON" if rt.desired else "OFF"
            stat = Text(f"[{chip}] {text}")
            stat.stylize(SEV_COLOR.get(sev, "grey62"))
            self.query_one(f"#sstatus-{spec.id}", Static).update(stat)
            self.view[spec.id] = text

            toggle = self.query_one(f"#tg-{spec.id}", Button)
            running = bool(o and o.running)
            toggle.label = "Stop" if (rt.desired and running) else "Start"
            toggle.disabled = not bool(o and o.exists)
            restart = self.query_one(f"#rs-{spec.id}", Button)
            restart.disabled = not bool(o and o.exists and o.running)

        feed = "\n".join(list(ctl.events)[-4:])
        self.query_one("#feed", Static).update(feed)

        # host network picture (refreshed at most every 4 s so key presses
        # stay snappy); gathered again after keyboard wake
        now = time.monotonic()
        if now - getattr(self, "_net_at", 0.0) > 4.0:
            try:
                pic = await asyncio.to_thread(ctl.ex.net_picture)
            except Exception:
                pic = {}
            self._pic = pic
            self._net_at = now
        pic = getattr(self, "_pic", {})
        lan = pic.get("lan") or {}
        ts = pic.get("ts") or {}
        self.last_net = pic.get("line") or "network summary unavailable"

        for i, (key, label, _action) in enumerate(EXTRAS):
            rowidx = i + len(self.services)
            sel = rowidx == self.selected
            mark = ">" if sel else " "
            num = rowidx + 1
            n = Text(f"  {mark} {num} {label}")
            if sel:
                n.stylize("bold #ffd54a")
            else:
                n.stylize("#cfe8ff")
            self.query_one(f"#ename-{i}", Static).update(n)
            status = Text("")
            if key == "net":
                status = self._net_status(lan)
            elif key == "tailscale":
                status = self._ts_status(ts)
            self.query_one(f"#estat-{i}", Static).update(status)

    @staticmethod
    def _net_status(lan: dict) -> Text:
        """Row status for the Network entry: connected-to name + health."""
        kind = lan.get("kind")
        conn = lan.get("connectivity", "unknown")
        name = str(lan.get("name") or "")
        word = {"full": "online", "limited": "limited",
                "none": "offline"}.get(conn, "?")
        color = {"full": "green", "limited": "yellow",
                 "none": "red"}.get(conn, "grey62")
        if kind in ("wifi", "ethernet") and name:
            return Text(f"{name} · {word}", style=color)
        if conn == "none":
            return Text("offline", style=color)
        return Text(word, style=color)

    @staticmethod
    def _ts_status(ts: dict) -> Text:
        """Row status for the Tailscale entry: state + number of peers."""
        if ts.get("state") == "online":
            peers = int(ts.get("peers") or 0)
            plural = "s" if peers != 1 else ""
            return Text(f"online · {peers} peer{plural}", style="green")
        return Text("offline", style="red")

    # ------------------------------------------------------------------
    # selection & actions
    def _selected_id(self) -> str:
        return self.services[self.selected].id

    def _set_selected(self, i: int) -> None:
        self.selected = i % (len(self.services) + len(EXTRAS))
        asyncio.create_task(self.refresh_ui())

    async def _run_manual(self, op: str) -> None:
        sid = self._selected_id()
        msg = await asyncio.to_thread(self.controller.manual, sid, op)
        await self.refresh_ui()
        if "not healthy yet" in msg:
            self.controller.push(f"{self.service_by_id[sid].title}: {msg}")

    def _boot_active(self) -> bool:
        # list navigation applies only on the boot (default) screen
        return self.screen is self.screen_stack[0]

    def action_up(self) -> None:
        if self._boot_active():
            self._set_selected(self.selected - 1)

    def action_down(self) -> None:
        if self._boot_active():
            self._set_selected(self.selected + 1)

    def _pick(self, i: int) -> None:
        if not self._boot_active() or not 0 <= i < len(self.services) + len(EXTRAS):
            return
        self.selected = i
        asyncio.create_task(self.refresh_ui())
        self._activate()

    def action_pick_1(self) -> None: self._pick(0)
    def action_pick_2(self) -> None: self._pick(1)
    def action_pick_3(self) -> None: self._pick(2)
    def action_pick_4(self) -> None: self._pick(3)
    def action_pick_5(self) -> None: self._pick(4)
    def action_pick_6(self) -> None: self._pick(5)
    def action_pick_7(self) -> None: self._pick(6)
    def action_pick_8(self) -> None: self._pick(7)
    def action_pick_9(self) -> None: self._pick(8)

    def action_start_selected(self) -> None:
        if self._boot_active() and self.selected < len(self.services):
            asyncio.create_task(self._run_manual("start"))

    def action_stop_selected(self) -> None:
        if self._boot_active() and self.selected < len(self.services):
            asyncio.create_task(self._run_manual("stop"))

    def action_restart_selected(self) -> None:
        if self._boot_active() and self.selected < len(self.services):
            asyncio.create_task(self._run_manual("restart"))

    def action_activate_selected(self) -> None:
        if self._boot_active():
            self._activate()

    def _activate(self) -> None:
        if self.selected < len(self.services):
            sid = self.services[self.selected].id
            op = "stop" if self.controller.rt[sid].desired else "start"
            asyncio.create_task(self._run_manual(op))
        else:
            _key, _label, action = EXTRAS[self.selected - len(self.services)]
            if not action:
                return  # status-only row (Tailscale)
            result = getattr(self, action)()
            if asyncio.iscoroutine(result):
                asyncio.create_task(result)

    def action_leave_console(self) -> None:
        self.exit_code = EXIT_CONSOLE
        self.exit(EXIT_CONSOLE)

    def action_leave_chromium(self) -> None:
        self.exit_code = EXIT_CHROMIUM
        self.exit(EXIT_CHROMIUM)

    def action_leave_xfce(self) -> None:
        self.exit_code = EXIT_XFCE
        self.exit(EXIT_XFCE)

    async def action_open_network(self) -> None:
        await self.push_screen(NetworkScreen(self.netio))

    def on_button_pressed(self, event: Button.Pressed) -> None:
        self._note_activity()
        bid = event.button.id or ""
        if bid.startswith("tg-"):
            sid = bid[3:]
            self._set_selected(self.services.index(self.service_by_id[sid]))
            op = "stop" if self.controller.rt[sid].desired else "start"
            asyncio.create_task(self._run_manual(op))
        elif bid.startswith("rs-"):
            sid = bid[3:]
            self._set_selected(self.services.index(self.service_by_id[sid]))
            asyncio.create_task(self._run_manual("restart"))
        elif bid == "leave-console":
            self.action_leave_console()
        elif bid == "leave-chromium":
            self.action_leave_chromium()
        elif bid == "leave-xfce":
            self.action_leave_xfce()
        elif bid == "leave-network":
            self.action_open_network()

    # ------------------------------------------------------------------
    # idle screensaver
    def _note_activity(self) -> None:
        self._last_activity = time.monotonic()

    def is_screensaver_up(self) -> bool:
        return self._saver is not None

    async def _enter_screensaver(self) -> None:
        if self._saver is not None or self.saver_idle <= 0:
            return
        self._idle_wake.clear()
        saver = ScreensaverScreen(self)
        self._saver = saver
        try:
            await self.push_screen(saver)
            self.call_after_refresh(self._pause_presentation_timers)
        except Exception:
            self._saver = None
            raise

    async def leave_screensaver(self) -> None:
        saver = self._saver
        if saver is None:
            return
        self._saver = None
        self._resume_presentation_timers()
        self._note_activity()
        self._idle_wake.set()
        # Reveal the console before contacting the host. A missing or slow host
        # must never leave an opaque screen covering otherwise usable controls.
        await self.pop_screen()
        await self.refresh_ui()
        if getattr(self.controller, "passive", False):
            asyncio.create_task(self._refresh_after_wake())

    async def _refresh_after_wake(self) -> None:
        try:
            await asyncio.to_thread(self.controller.run_tick)
        except Exception:
            from services import Status
            for spec in self.services:
                self.controller.statuses[spec.id] = Status(2, "supervisor unavailable")
            self.controller.push("supervisor unavailable; status will retry while visible")
        await self.refresh_ui()

    async def _watch_screensaver(self) -> None:
        while True:
            # No idle-watch polling while the black screen waits for a key.
            if self._saver is not None:
                await self._idle_wake.wait()
            await asyncio.sleep(self.saver_watch_s)
            try:
                if self.saver_idle <= 0 or self._saver is not None:
                    continue
                if time.monotonic() - self._last_activity >= self.saver_idle:
                    await self._enter_screensaver()
            except asyncio.CancelledError:
                raise
            except Exception as e:
                self.controller.push(f"screensaver: {e}")

    def action_preview_screensaver(self) -> None:
        if self._boot_active():
            asyncio.create_task(self._enter_screensaver())

    def action_quit(self) -> None:
        # ctrl+q while the screensaver is up only wakes it; a second press quits
        if self._saver is not None:
            asyncio.create_task(self.leave_screensaver())
            return
        self.exit_code = EXIT_CONSOLE
        self.exit(EXIT_CONSOLE)

    def _pause_presentation_timers(self) -> None:
        # Wait until the first black frame has painted, then stop widget/animation timers.
        if not self.is_screensaver_up():
            return
        seen = set()
        owners = [self]
        for screen in self.screen_stack:
            owners.extend([screen, *screen.walk_children()])
        for owner in owners:
            for timer in list(getattr(owner, "_timers", ())):
                if id(timer) not in seen and timer._active.is_set():
                    seen.add(id(timer))
                    timer.pause()
                    self._presentation_timers.append(timer)

    def _resume_presentation_timers(self) -> None:
        timers, self._presentation_timers = self._presentation_timers, []
        for timer in timers:
            timer.resume()

    async def on_event(self, event: events.Event) -> None:
        # Observe originating keyboard input before an Input/modal can consume it.
        if isinstance(event, events.Key) and not event.is_forwarded:
            self._note_activity()
            if self.is_screensaver_up():
                event.stop()
                event.prevent_default()
                asyncio.create_task(self.leave_screensaver())
                return
        elif isinstance(event, (events.MouseDown, events.Paste)) and not self.is_screensaver_up():
            self._note_activity()
        await super().on_event(event)

    # keyboard / mouse activity resets the idle timer
    def on_key(self, event: events.Key) -> None:
        self._note_activity()

    def on_mouse_down(self, event: events.MouseDown) -> None:
        self._note_activity()


def main() -> int:
    app = BootApp()
    code = app.run()
    if code is None:
        code = app.exit_code
    return int(code) if code is not None else EXIT_CONSOLE


if __name__ == "__main__":
    sys.exit(main())

"""controller.py — drives the supervisor: gather real state, plan, act, log.

Holds mutable runtime state and an event feed. UI-agnostic (no Textual
imports) so it can be tested headlessly with a fake Executor.
"""
from __future__ import annotations

import os
import time
from collections import deque
from datetime import datetime, timezone

from services import (
    SERVICES,
    SERVICE_BY_ID,
    Cfg,
    RT,
    plan,
    urls_for,
)


class Controller:
    def __init__(
        self,
        executor,
        cfg: Cfg | None = None,
        log_path: str | None = None,
        tick_s: float = 5.0,
    ):
        self.ex = executor
        self.cfg = cfg or Cfg()
        self.tick_s = tick_s
        self.rt: dict[str, RT] = {s.id: RT() for s in SERVICES}
        self.obs: dict[str, "Observed"] = {}
        self.statuses: dict[str, object] = {}
        self.notes: dict[str, str] = {}
        self.events: deque[str] = deque(maxlen=6)
        self.docker_ok = False
        self.docker_noted = False
        self._was_running: dict[str, bool] = {}
        self._last_note: dict[str, str] = {}
        self.log_path = log_path or os.path.join(
            os.path.expanduser("~"), ".cache", "webagent-boot.log"
        )
        self._start_log()

    # ------------------------------------------------------------------
    def _start_log(self) -> None:
        try:
            os.makedirs(os.path.dirname(self.log_path), exist_ok=True)
            with open(self.log_path, "w") as fh:
                fh.write(f"WebAgent boot run: {datetime.now(timezone.utc).isoformat()}\n")
                fh.write("Boot dashboard started; supervising all services.\n")
        except Exception:
            pass

    def append_log(self, line: str) -> None:
        try:
            with open(self.log_path, "a") as fh:
                fh.write(f"{time.strftime('%Y-%m-%dT%H:%M:%S%z')} {line}\n")
        except Exception:
            pass

    def push(self, msg: str) -> None:
        stamp = time.strftime("%H:%M:%S")
        self.events.append(f"{stamp}  {msg}")
        self.append_log(msg)

    # ------------------------------------------------------------------
    def gather(self, now: float | None = None) -> None:
        self.docker_ok = self.ex.docker_ok()
        online = self.ex.internet_ok()
        for spec in SERVICES:
            o = self.ex.inspect(spec.container)
            if spec.role == "app" and o.exists and o.running:
                url, fb = urls_for(spec)
                ok, ms, txt = self.ex.probe(url, fb)
                if ok:
                    o.http_ok = True
                    o.http_text = txt
                elif txt.startswith("unreachable:"):
                    # Host cannot connect at all - trust the container's own
                    # docker healthcheck (operator-defined liveness).
                    o.http_ok = o.docker_health == "healthy"
                    o.http_text = txt.replace("unreachable:", "host-unreachable:")
                else:
                    o.http_ok = False
                    o.http_text = txt
                o.http_ms = ms
            if spec.role == "tunnel" and o.exists and o.running and online:
                url, _ = urls_for(spec)
                ok, ms, txt = self.ex.probe(url, None)
                o.http_ms = ms
                if ok:
                    o.http_ok = True
                    o.http_text = txt
                elif txt.startswith("HTTP 5"):
                    o.http_ok = False
                    o.http_text = txt
                else:
                    o.http_ok = None
                    o.http_text = txt
            self.obs[spec.id] = o

    def run_tick(self) -> None:
        now = time.time()
        self.gather(now)
        actions, statuses, notes = plan(
            self.obs, self.rt, now, self.cfg, self.docker_ok
        )
        self.statuses = statuses
        self.notes = notes

        # docker-daemon transition note (once per down/up)
        if not self.docker_ok and not self.docker_noted:
            self.docker_noted = True
            self.push("docker daemon not ready - waiting")
        elif self.docker_ok and self.docker_noted:
            self.docker_noted = False
            self.push("docker daemon ready")

        # run planned actions
        for a in actions:
            spec = SERVICE_BY_ID[a.service]
            if a.kind == "netconnect":
                net = getattr(self.obs.get(a.service), "netmode", "") or "bridge"
                if net == "default":
                    net = "bridge"
                ok, msg = self.ex.network_connect(spec.container, net)
            else:
                ok, msg = self.ex.container_action(spec.container, a.kind)
            rt = self.rt[a.service]
            if ok:
                rt.last_attempt = now
                rt.attempts.append(now)
            word = "ok" if ok else "FAILED"
            self.push(f"{a.kind} {spec.container}: {word} ({a.reason})")
            if not ok:
                self.push(f"  -> {msg}")

        # transitions worth reporting
        for spec in SERVICES:
            o = self.obs.get(spec.id)
            if not o:
                continue
            was = self._was_running.get(spec.id)
            if was is False and o.running:
                self.push(f"{spec.container} is running")
            elif was is True and not o.running and o.exists:
                self.push(f"{spec.container} stopped")
            self._was_running[spec.id] = o.running

        # notes (waiting/backoff/attention) - report when they change
        for sid, note in notes.items():
            if self._last_note.get(sid) != note:
                self._last_note[sid] = note
                self.push(f"{SERVICE_BY_ID[sid].container}: {note}")
        for sid in list(self._last_note):
            if sid not in notes:
                self._last_note.pop(sid, None)

    # ------------------------------------------------------------------
    def manual(self, sid: str, op: str) -> str:
        """User-initiated start/stop/restart/toggle. Returns status text."""
        spec = SERVICE_BY_ID[sid]
        rt = self.rt[sid]

        if op == "toggle":
            rt.desired = not rt.desired
            op = "start" if rt.desired else "stop"

        if op == "start":
            rt.desired = True
            if spec.role == "tunnel":
                app = SERVICE_BY_ID[f"{spec.stack}-app"]
                app_obs = self.obs.get(app.id)
                app_ok = bool(app_obs and app_obs.http_ok)
                if not app_ok:
                    return f"tunnel not started - {app.container} is not healthy yet"
        elif op == "stop":
            rt.desired = False
        elif op == "restart":
            rt.desired = True
        else:
            return f"unknown action {op}"

        # manual control resets the crash guard
        rt.attempts = []
        rt.crash = False
        rt.last_attempt = 0.0

        ok, msg = self.ex.container_action(spec.container, op)
        if ok:
            self.push(f"manual {op} {spec.container}: ok")
            self.run_tick()
        else:
            self.push(f"manual {op} {spec.container}: FAILED - {msg}")
        return msg

"""dockerio.py — real-world I/O for the boot dashboard.

Thin wrapper around docker + HTTP probes. Swap in a fake Executor in tests;
pass dry_run=True to log actions instead of executing them.
"""
from __future__ import annotations

import datetime as _dt
import json
import os
import subprocess
import time
import urllib.error
import urllib.request

from services import Observed


def _run(cmd: list[str], timeout: float = 90.0) -> tuple[int, str, str]:
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout.strip(), p.stderr.strip()
    except subprocess.TimeoutExpired:
        return 124, "", "timed out"
    except FileNotFoundError:
        return 127, "", "command not found"


def _parse_started_epoch(iso: str) -> float | None:
    iso = (iso or "").strip()
    if not iso:
        return None
    try:
        dt = _dt.datetime.fromisoformat(iso.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=_dt.timezone.utc)
        return dt.timestamp()
    except ValueError:
        return None


_UA = ("Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 "
       "(KHTML, like Gecko) Chrome/120.0 Safari/537.36")


def _request(url: str) -> urllib.request.Request:
    return urllib.request.Request(url, headers={"User-Agent": _UA})


class Executor:
    """Real executor: docker + HTTP + network summary."""

    def __init__(self, dry_run: bool = False):
        self.dry_run = dry_run
        self.dry_log: list[tuple[str, str]] = []     # (container, action)
        self._internet_cache: tuple[float, bool] = (0.0, False)

    # --- docker ---------------------------------------------------------
    def docker_ok(self) -> bool:
        rc, _, _ = _run(["docker", "info"], timeout=20.0)
        return rc == 0

    def inspect(self, container: str) -> Observed:
        rc, out, err = _run(
            ["docker", "inspect", "--format",
             "{{.State.Running}}|{{.State.StartedAt}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}|{{.HostConfig.NetworkMode}}|{{len .NetworkSettings.Networks}}",
             container],
            timeout=30.0,
        )
        if rc != 0:
            if "No such object" in err:
                return Observed(exists=False)
            # docker not reachable or other error: keep unknown-but-existing
            return Observed(exists=True)
        parts = out.split("|", 4)
        running = parts[0].strip().lower() == "true"
        started = _parse_started_epoch(parts[1] if len(parts) > 1 else "")
        health = parts[2].strip() if len(parts) > 2 else ""
        netmode = parts[3].strip() if len(parts) > 3 else ""
        net_attached = True
        if len(parts) > 4:
            net_attached = parts[4].strip() != "0"
        return Observed(exists=True, running=running, docker_health=health,
                        started_epoch=started, netmode=netmode,
                        net_attached=net_attached)

    def probe(self, url: str, fallback: str | None = None,
              timeout: float = 3.0) -> tuple[bool, float | None, str]:
        """Return (ok, elapsed_ms, short_result)."""
        for target in (url, fallback):
            if not target:
                continue
            t0 = time.perf_counter()
            try:
                with urllib.request.urlopen(_request(target), timeout=timeout) as resp:
                    resp.read(64)
                    ms = (time.perf_counter() - t0) * 1000.0
                    return True, ms, str(resp.status)
            except urllib.error.HTTPError as e:
                ms = (time.perf_counter() - t0) * 1000.0
                if e.code == 404 and target is url and fallback:
                    continue
                return False, ms, f"HTTP {e.code}"
            except urllib.error.URLError as e:
                ms = (time.perf_counter() - t0) * 1000.0
                reason = getattr(e, "reason", None)
                text = "error"
                if isinstance(reason, ConnectionRefusedError):
                    text = "refused"
                elif isinstance(reason, TimeoutError):
                    text = "timeout"
                elif isinstance(reason, OSError):
                    text = getattr(reason, "strerror", "error")
                return False, ms, f"unreachable:{text}"
            except OSError as e:
                ms = (time.perf_counter() - t0) * 1000.0
                if isinstance(e, TimeoutError):
                    return False, ms, "unreachable:timeout"
                text = getattr(e, "reason", "error")
                if isinstance(text, Exception):
                    text = str(e)
                return False, ms, f"unreachable:{text}"
        return False, None, "no url"

    def container_action(self, container: str, action: str) -> tuple[bool, str]:
        """start | stop | restart. Returns (ok, message)."""
        if self.dry_run:
            self.dry_log.append((container, action))
            return True, f"dry-run: would {action} {container}"
        rc, out, err = _run(["docker", action, container], timeout=120.0)
        if rc == 0:
            return True, (out or err or f"{action} ok")
        return False, (err or f"{action} failed (rc {rc})")

    def network_connect(self, container: str, network: str = "bridge") -> tuple[bool, str]:
        """Re-attach a detached container to its docker network."""
        if self.dry_run:
            self.dry_log.append((container, f"netconnect:{network}"))
            return True, f"dry-run: would connect {container} to {network}"
        rc, out, err = _run(["docker", "network", "connect", network, container], timeout=60.0)
        if rc == 0:
            return True, (out or err or f"connected {container} to {network}")
        return False, (err or f"network connect failed (rc {rc})")

    def internet_ok(self) -> bool:
        """Cached: can the host reach the public internet?"""
        return self._internet_ok()

    # --- network summary -------------------------------------------------
    def _internet_ok(self) -> bool:
        now = time.monotonic()
        if now - self._internet_cache[0] < 30.0:
            return self._internet_cache[1]
        ok = False
        try:
            with urllib.request.urlopen(_request("https://www.cloudflare.com/"), timeout=3.0) as r:
                r.read(32)
                ok = True
        except Exception:
            ok = False
        self._internet_cache = (now, ok)
        return ok

    def net_summary(self) -> str:
        """One-line network picture for the footer area."""
        try:
            bits = []
            rc, out, _ = _run(["ip", "-4", "route", "show", "default"], timeout=10.0)
            iface = gw = ""
            if rc == 0 and out:
                fields = out.split()
                for i, f in enumerate(fields):
                    if f == "dev":
                        iface = fields[i + 1]
                    elif f == "via":
                        gw = fields[i + 1]
            if iface:
                if os.path.isdir(f"/sys/class/net/{iface}/wireless"):
                    rc2, ssid, _ = _run(["iwgetid", "-r"], timeout=10.0)
                    net = f"wifi {iface} ({ssid})" if rc2 == 0 and ssid else f"wifi {iface}"
                else:
                    net = iface
                rc2, out2, _ = _run(["ip", "-4", "-o", "addr", "show", "dev", iface], timeout=10.0)
                addr = ""
                for line in out2.splitlines():
                    parts = line.split()
                    if len(parts) >= 4:
                        addr = parts[3].split("/")[0]
                        break
                net += f" {addr}"
                if gw:
                    net += f" gw {gw}"
                bits.append(net)
            else:
                bits.append("no default route")

            rc2, out2, _ = _run(["ip", "-4", "-o", "addr", "show", "dev", "tailscale0"], timeout=10.0)
            ts = ""
            if rc2 == 0:
                for line in out2.splitlines():
                    parts = line.split()
                    if len(parts) >= 4 and parts[3].startswith("100."):
                        ts = parts[3].split("/")[0]
                        break
            bits.append(f"tailscale {ts}" if ts else "tailscale off")

            bits.append("internet on" if self._internet_ok() else "internet OFF")
            return " | ".join(bits)
        except Exception as e:  # never let a summary failure break the UI
            return f"net summary unavailable ({e})"
    def net_picture(self) -> dict:
        """LAN link + Tailscale state + one-line summary for the dashboard.

        Returns {"lan": {...}, "ts": {...}, "line": "..."}. Never raises.
        Network names (wifi SSID / wired profile) are preferred over the
        numeric address; health words come from NetworkManager connectivity.
        """
        try:
            lan = {"kind": "none", "name": "", "addr": "", "gw": "",
                   "connectivity": "unknown", "internet": False}

            # NetworkManager connectivity state -> health word for the row
            rc, out, _ = _run(["nmcli", "-t", "general", "status"], timeout=10.0)
            conn = ""
            if rc == 0 and out:
                parts = out.split(":")
                conn = parts[1] if len(parts) > 1 else ""
            if conn not in ("full", "limited", "none"):
                conn = "unknown"
            lan["connectivity"] = conn

            # default route -> uplink interface + gateway
            iface = ""
            rc, out, _ = _run(["ip", "-4", "route", "show", "default"], timeout=10.0)
            if rc == 0 and out:
                fields = out.split()
                for pos, tok in enumerate(fields):
                    if tok == "dev" and pos + 1 < len(fields):
                        iface = fields[pos + 1]
                    elif tok == "via" and pos + 1 < len(fields):
                        lan["gw"] = fields[pos + 1]

            addr = ""
            if iface:
                rc, out, _ = _run(
                    ["ip", "-4", "-o", "addr", "show", "dev", iface], timeout=10.0
                )
                for line in out.splitlines():
                    parts = line.split()
                    if len(parts) >= 4:
                        addr = parts[3].split("/")[0]
                        break
                lan["addr"] = addr

                wireless = os.path.isdir("/sys/class/net/" + iface + "/wireless")
                lan["kind"] = "wifi" if wireless else "ethernet"

                # show the network by name: active wifi SSID first, otherwise
                # the wired/wifi profile name, then the interface
                name = ""
                if wireless:
                    rc, out, _ = _run(
                        ["nmcli", "-t", "-f", "IN-USE,SSID", "device",
                         "wifi", "list"],
                        timeout=15.0,
                    )
                    for line in out.splitlines():
                        bits = line.split(":")
                        if len(bits) >= 2 and bits[0] == "*":
                            name = bits[1]
                            break
                if not name:
                    rc, out, _ = _run(
                        ["nmcli", "-t", "-f", "TYPE,NAME", "connection",
                         "show", "--active"],
                        timeout=10.0,
                    )
                    want = "802-11-wireless" if wireless else "802-3-ethernet"
                    for line in out.splitlines():
                        bits = line.split(":")
                        if len(bits) >= 2 and bits[0] == want:
                            name = bits[1]
                            break
                lan["name"] = name or iface

            lan["internet"] = lan["connectivity"] == "full"

            # Tailscale: online flag + peer count via its own status API
            ts = {"state": "offline", "peers": 0}
            rc, out, _ = _run(["tailscale", "status", "--json"], timeout=15.0)
            if rc == 0 and out:
                try:
                    data = json.loads(out)
                    self_rec = data.get("Self") or {}
                    if bool(self_rec.get("Online")):
                        ts = {"state": "online",
                              "peers": len(data.get("Peer") or [])}
                except Exception:
                    ts = {"state": "offline", "peers": 0}

            # one-line summary kept for the screensaver card
            bits = []
            if lan.get("kind") in ("wifi", "ethernet"):
                lp = [lan.get("kind"), lan.get("name") or "",
                      lan.get("addr") or ""]
                bits.append(" ".join(x for x in lp if x))
            else:
                bits.append("no link")
            if ts.get("state") == "online":
                peers = ts.get("peers") or 0
                bits.append("tailscale online (" + str(peers) +
                            " peer" + ("" if peers == 1 else "s") + ")")
            else:
                bits.append("tailscale off")
            bits.append("internet on" if lan["internet"] else "internet OFF")
            line = " | ".join(bits)
            return {"lan": lan, "ts": ts, "line": line}
        except Exception as exc:  # never let a summary failure break the UI
            return {
                "lan": {"kind": "none", "name": "", "addr": "", "gw": "",
                        "connectivity": "unknown", "internet": False},
                "ts": {"state": "offline", "peers": 0},
                "line": "network summary unavailable (" + str(exc) + ")",
            }

"""netio.py — NetworkManager (nmcli) wrapper for the Network screen.

Same injectable/testable style as dockerio.py. Read methods return plain
dicts/lists; mutating methods return (ok, message). dry_run=True logs
instead of executing.
"""
from __future__ import annotations

from typing import Optional

from dockerio import _run


def _split(line: str) -> list[str]:
    """Split an nmcli `-e yes` terse line, honouring escaped colons."""
    parts: list[str] = []
    cur: list[str] = []
    i = 0
    while i < len(line):
        c = line[i]
        if c == "\\" and i + 1 < len(line):
            cur.append(line[i + 1])
            i += 2
            continue
        if c == ":":
            parts.append("".join(cur))
            cur = []
            i += 1
            continue
        cur.append(c)
        i += 1
    parts.append("".join(cur))
    return parts


class NetIO:
    """nmcli access. Swap in FakeNetIO for tests."""

    def __init__(self, dry_run: bool = False):
        self.dry_run = dry_run
        self.dry_log: list[tuple[str, ...]] = []

    def _run(self, cmd: list[str], timeout: float = 60.0):
        return _run(cmd, timeout)

    def _nm(self, *args: str, timeout: float = 60.0):
        return self._run(["nmcli", "-e", "yes", *args], timeout)

    # ---- status -----------------------------------------------------
    def status(self) -> dict:
        rc, out, _ = self._nm("-t", "general", "status")
        fields = _split(out) if out else []
        state = fields[0] if fields else "unknown"
        connectivity = fields[1] if len(fields) > 1 else "unknown"
        rc, radio, _ = self._nm("radio", "wifi")
        wifi_on = radio.strip().lower() == "enabled"
        return {"state": state, "connectivity": connectivity, "wifi_on": wifi_on}

    def wifi_device(self) -> Optional[str]:
        rc, out, _ = self._nm("-t", "-f", "DEVICE,TYPE,STATE", "device")
        for line in out.splitlines():
            f = _split(line)
            if len(f) >= 2 and f[1] == "wifi":
                return f[0]
        return None

    def device_ip(self, device: str) -> str:
        rc, out, _ = self._nm("-g", "IP4.ADDRESS", "device", "show", device)
        return out.strip() if rc == 0 and out.strip() else "no ip"

    # ---- wifi -------------------------------------------------------
    def wifi_list(self) -> list[dict]:
        rc, out, _ = self._nm("-t", "-f", "IN-USE,SSID,SIGNAL,SECURITY",
                              "device", "wifi", "list")
        items: list[dict] = []
        for line in out.splitlines():
            f = _split(line)
            if len(f) < 4 or not f[1]:
                continue
            try:
                signal = int(f[2])
            except ValueError:
                signal = 0
            items.append({
                "ssid": f[1],
                "signal": signal,
                "security": f[3] or "",
                "active": f[0] == "*",
            })
        # one row per SSID: prefer the active entry, otherwise strongest
        best: dict[str, dict] = {}
        for it in items:
            key = it["ssid"]
            prev = best.get(key)
            if prev is None or (it["active"] and not prev["active"]) or                (it["active"] == prev["active"] and it["signal"] > prev["signal"]):
                best[key] = it
        return list(best.values())

    def wifi_rescan(self) -> tuple[bool, str]:
        if self.dry_run:
            self.dry_log.append(("wifi_rescan",))
            return True, "dry-run: rescan"
        rc, out, err = self._nm("device", "wifi", "rescan", timeout=30.0)
        if rc == 0:
            return True, "scan refreshed"
        return False, err or "rescan failed"

    def wifi_connect(self, ssid: str, password: Optional[str]) -> tuple[bool, str]:
        if self.dry_run:
            self.dry_log.append(("wifi_connect", ssid, password or ""))
            return True, f"dry-run: would connect {ssid}"
        cmd = ["device", "wifi", "connect", ssid]
        if password:
            cmd += ["password", password]
        rc, out, err = self._nm(*cmd, timeout=60.0)
        if rc == 0:
            return True, f"connected to {ssid}"
        return False, err or out or f"connect failed (rc {rc})"

    def wifi_disconnect(self) -> tuple[bool, str]:
        dev = self.wifi_device()
        if self.dry_run:
            self.dry_log.append(("wifi_disconnect", dev or "wifi"))
            return True, "dry-run: would disconnect"
        if not dev:
            return False, "no wifi device found"
        rc, out, err = self._nm("device", "disconnect", dev, timeout=30.0)
        if rc == 0:
            return True, "wifi disconnected"
        return False, err or "disconnect failed"

    def _profile_for_ssid(self, ssid: str) -> Optional[str]:
        rc, out, _ = self._nm("-t", "-f", "NAME,TYPE", "connection", "show")
        for line in out.splitlines():
            f = _split(line)
            if len(f) >= 2 and f[1] == "802-11-wireless":
                rc2, ss, _ = self._nm("-g", "802-11-wireless.ssid",
                                      "connection", "show", f[0])
                if rc2 == 0 and ss.strip() == ssid:
                    return f[0]
        return None

    def wifi_forget(self, ssid: str) -> tuple[bool, str]:
        if self.dry_run:
            self.dry_log.append(("wifi_forget", ssid))
            return True, f"dry-run: would forget {ssid}"
        name = self._profile_for_ssid(ssid)
        if not name:
            return False, f"no saved profile for {ssid}"
        rc, out, err = self._nm("connection", "delete", name, timeout=30.0)
        if rc == 0:
            return True, f"forgot {ssid}"
        return False, err or "delete failed"

    def wifi_radio(self, on: bool) -> tuple[bool, str]:
        if self.dry_run:
            self.dry_log.append(("wifi_radio", "on" if on else "off"))
            return True, f"dry-run: radio {'on' if on else 'off'}"
        rc, out, err = self._nm("radio", "wifi", "on" if on else "off")
        if rc == 0:
            return True, f"wifi radio {'on' if on else 'off'}"
        return False, err or "radio toggle failed"

    # ---- ethernet ---------------------------------------------------
    def ethernet_devices(self) -> list[dict]:
        rc, out, _ = self._nm("-t", "-f", "DEVICE,TYPE,STATE,CONNECTION", "device")
        virtual = ("veth", "docker", "br-", "virbr", "tun", "tap", "tailscale", "lo")
        items: list[dict] = []
        for line in out.splitlines():
            f = _split(line)
            if len(f) >= 3 and f[1] == "ethernet"                and not f[0].startswith(virtual):
                ip = self.device_ip(f[0]) if f[2] == "connected" else ""
                items.append({
                    "device": f[0],
                    "state": f[2],
                    "connection": f[3] if len(f) > 3 else "",
                    "ip": ip,
                })
        return items

    def ethernet_set(self, device: str, up: bool) -> tuple[bool, str]:
        if self.dry_run:
            self.dry_log.append(("ethernet_set", device, "up" if up else "down"))
            return True, f"dry-run: {'connect' if up else 'disconnect'} {device}"
        rc, out, err = self._nm("device", "connect" if up else "disconnect",
                                device, timeout=60.0)
        if rc == 0:
            return True, f"{device} {'connected' if up else 'disconnected'}"
        return False, err or "operation failed"

"""netscreen.py - Network screen (Wi-Fi + Ethernet) for the boot dashboard."""
from __future__ import annotations

import asyncio

from textual.app import ComposeResult
from textual.binding import Binding
from textual.containers import Horizontal
from textual.screen import Screen
from textual.widgets import Button, Input, Label, ListItem, ListView, Static
from rich.text import Text

from netio import NetIO


class PasswordModal(Screen):
    """Masked password prompt for a secured network."""

    CSS = """
    #pw_title { height: 1; background: #003333; color: #9fd8d8; }
    Input { width: 40; margin: 1 0; }
    """

    def __init__(self, ssid: str, callback):
        super().__init__()
        self.ssid = ssid
        self.callback = callback

    def compose(self) -> ComposeResult:
        yield Static(f" Password for {self.ssid} ", id="pw_title")
        yield Input(password=True, id="pw")
        with Horizontal():
            yield Button("Connect", id="pw-ok")
            yield Button("Cancel", id="pw-cancel")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "pw-ok":
            self.callback(self.ssid, self.query_one("#pw", Input).value)
            self.dismiss()
        elif event.button.id == "pw-cancel":
            self.dismiss()

    def on_input_submitted(self, event) -> None:
        self.callback(self.ssid, event.value)
        self.dismiss()


class NetworkScreen(Screen):
    """Wi-Fi and Ethernet control surface, pushed from the boot screen."""

    BINDINGS = [
        Binding("escape", "back", "back", show=False),
        Binding("q", "back", "back", show=False),
        Binding("w", "wifi_mode", "wifi", show=False),
        Binding("e", "eth_mode", "ethernet", show=False),
        Binding("r", "refresh", "rescan", show=False),
        Binding("d", "disconnect", "disconnect", show=False),
        Binding("f", "forget", "forget", show=False),
        Binding("o", "radio", "radio", show=False),
    ]

    CSS = """
    #net_title { height: 1; background: #003333; color: #9fd8d8; }
    #net_status { height: 3; color: #b0b0b0; }
    #net_list { height: 1fr; }
    #net_hint { height: 1; color: #6b6b6b; }
    ListItem { padding: 0 0; }
    """

    def __init__(self, netio: NetIO):
        super().__init__()
        self.netio = netio
        self.mode = "wifi"
        self.items: list[dict] = []
        self.status_data: dict = {}
        self.wifi_on = True
        self.conn = "unknown"
        self.wifi_ip = ""
        self.msg = ""

    def compose(self) -> ComposeResult:
        yield Static(" Network ", id="net_title")
        yield Static("", id="net_status")
        yield ListView(id="net_list")
        yield Static(" w wifi  e ethernet  enter connect  r rescan  "
                     "d disconnect  f forget  o radio  q back", id="net_hint")

    def on_mount(self) -> None:
        self._timer = self.set_interval(8.0, self._auto)
        asyncio.create_task(self._refresh())
        self.query_one("#net_list", ListView).focus()

    def on_screen_suspend(self) -> None:
        # Covered network/password screens do no periodic network presentation work.
        timer = getattr(self, "_timer", None)
        if timer is not None:
            timer.pause()

    def on_screen_resume(self) -> None:
        timer = getattr(self, "_timer", None)
        if timer is not None:
            timer.resume()
            asyncio.create_task(self._refresh())

    def on_unmount(self) -> None:
        t = getattr(self, "_timer", None)
        if t is not None:
            t.stop()

    # ---- data --------------------------------------------------------
    def _load_all(self) -> None:
        self.status_data = self.netio.status()
        self.wifi_on = bool(self.status_data.get("wifi_on"))
        self.conn = self.status_data.get("connectivity", "unknown")
        self.wifi_ip = ""
        if self.mode == "wifi":
            self.items = self.netio.wifi_list()
            dev = self.netio.wifi_device()
            if dev:
                self.wifi_ip = self.netio.device_ip(dev)
        else:
            self.items = self.netio.ethernet_devices()

    # ---- rendering ---------------------------------------------------
    def _item_text(self, it: dict) -> Text:
        if self.mode == "wifi":
            sig = int(it.get("signal", 0))
            color = "green" if sig >= 60 else ("yellow" if sig >= 30 else "red")
            mark = " * " if it.get("active") else "   "
            sec = it.get("security") or "open"
            t = Text(f"{mark}{it.get('ssid', '?'):24s}  {sig:3d}%  {sec}")
            t.stylize(color)
            if it.get("active"):
                t.stylize("bold")
            return t
        else:
            state = it.get("state", "?")
            color = "green" if state == "connected" else "grey62"
            t = Text(f"   {it.get('device', '?'):10s}  {state:12s}  "
                     f"{it.get('ip') or '-':15s}  {it.get('connection', '')}")
            t.stylize(color)
            return t

    def _status_text(self) -> str:
        head = "WIFI" if self.mode == "wifi" else "ETHERNET"
        head += f"   internet {self.conn}"
        if self.mode == "wifi":
            head += f"   radio {'on' if self.wifi_on else 'off'}"
        lines = [head]
        if self.mode == "wifi":
            active = next((x for x in self.items if x.get("active")), None)
            if active:
                sec = active.get("security") or "open"
                lines.append(f"connected: {active['ssid']}  {active['signal']}%  {sec}  {self.wifi_ip}")
            else:
                lines.append("not connected")
        else:
            for d in self.items:
                lines.append(f"{d['device']}  {d['state']}  {d.get('ip') or '-'}")
        if self.msg:
            lines.append(f"  {self.msg}")
        return "\n".join(lines)

    def _update_status(self) -> None:
        if not self.is_mounted or self.app.screen is not self:
            return
        self.query_one("#net_status", Static).update(self._status_text())

    def _rebuild(self) -> None:
        if not self.is_mounted or self.app.screen is not self:
            return
        self._update_status()
        lv = self.query_one("#net_list", ListView)
        lv.clear()
        for it in self.items:
            lv.append(ListItem(Label(self._item_text(it))))
        if self.items:
            lv.index = 0

    # ---- refresh / modes --------------------------------------------
    async def _refresh(self) -> None:
        await asyncio.to_thread(self._load_all)
        self._rebuild()

    async def _auto(self) -> None:
        if self.app.screen is not self:
            return
        await asyncio.to_thread(self._load_all)
        self._update_status()

    def action_refresh(self) -> None:
        asyncio.create_task(self._refresh())

    def action_wifi_mode(self) -> None:
        self.mode = "wifi"
        self.msg = "showing wifi networks"
        asyncio.create_task(self._refresh())

    def action_eth_mode(self) -> None:
        self.mode = "eth"
        self.msg = "showing ethernet devices"
        asyncio.create_task(self._refresh())

    def action_back(self) -> None:
        self.app.pop_screen()

    # ---- actions -----------------------------------------------------
    def on_list_view_selected(self, event) -> None:
        asyncio.create_task(self._connect())

    async def _connect(self) -> None:
        if not self.is_mounted or self.app.screen is not self:
            return
        i = self.query_one("#net_list", ListView).index
        if i is None or i >= len(self.items):
            return
        it = self.items[i]
        if self.mode == "eth":
            up = it.get("state") != "connected"
            ok, msg = await asyncio.to_thread(self.netio.ethernet_set, it["device"], up)
        else:
            if it.get("security"):
                def _cb(ssid, pw):
                    if pw is not None:
                        asyncio.create_task(self._finish_connect(ssid, pw))
                await self.app.push_screen(PasswordModal(it["ssid"], _cb))
                return
            else:
                ok, msg = await asyncio.to_thread(self.netio.wifi_connect, it["ssid"], None)
        self.msg = msg
        await self._refresh()

    async def _finish_connect(self, ssid: str, pw: str) -> None:
        ok, msg = await asyncio.to_thread(self.netio.wifi_connect, ssid, pw)
        self.msg = msg
        await self._refresh()

    def action_disconnect(self) -> None:
        asyncio.create_task(self._disconnect())

    async def _disconnect(self) -> None:
        if self.mode == "wifi":
            ok, msg = await asyncio.to_thread(self.netio.wifi_disconnect)
        else:
            i = self.query_one("#net_list", ListView).index
            if i is None or i >= len(self.items):
                return
            ok, msg = await asyncio.to_thread(self.netio.ethernet_set, self.items[i]["device"], False)
        self.msg = msg
        await self._refresh()

    def action_forget(self) -> None:
        asyncio.create_task(self._forget())

    async def _forget(self) -> None:
        if self.mode != "wifi":
            return
        i = self.query_one("#net_list", ListView).index
        if i is None or i >= len(self.items):
            return
        ssid = self.items[i]["ssid"]
        ok, msg = await asyncio.to_thread(self.netio.wifi_forget, ssid)
        self.msg = msg
        await self._refresh()

    def action_radio(self) -> None:
        asyncio.create_task(self._radio())

    async def _radio(self) -> None:
        ok, msg = await asyncio.to_thread(self.netio.wifi_radio, not self.wifi_on)
        self.wifi_on = not self.wifi_on
        self.msg = msg
        await self._refresh()

"""services.py — WebAgent boot dashboard: stack definitions + pure supervisor logic.

No I/O and no UI in this module. plan() is a pure function of a state
snapshot plus engine timers, so it can be unit-tested without docker.
"""
from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Optional


# ---------------------------------------------------------------------------
# Stack definitions (prod + dev live on this physical server)
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class ServiceSpec:
    id: str              # e.g. "prod-app"
    stack: str           # "prod" | "dev"
    role: str            # "app" | "tunnel"
    container: str       # docker container name
    label: str           # short label (legacy)
    domain: str          # public domain it serves
    title: str           # full display line in the boot list

SERVICES: list[ServiceSpec] = [
    ServiceSpec("prod-app",    "prod", "app",    "webagent",                       "WebAgent",  "webagent.live",     "App Webagent"),
    ServiceSpec("prod-tunnel", "prod", "tunnel", "cloudflared-webagent-named",     "Tunnel",    "webagent.live",     "Tunnel webagent.live"),
    ServiceSpec("dev-app",     "dev",  "app",    "webagent-dev",                   "WebAgent",  "dev.webagent.live", "App Webagent-dev"),
    ServiceSpec("dev-tunnel",  "dev",  "tunnel", "cloudflared-webagent-dev-named", "Tunnel",    "dev.webagent.live", "Tunnel dev.webagent.live"),
]

SERVICE_BY_ID: dict[str, ServiceSpec] = {s.id: s for s in SERVICES}

# Public URLs the tunnels serve; probed to catch a running-but-dead tunnel.
TUNNEL_URLS: dict[str, str] = {
    "prod-tunnel": "https://webagent.live/app",
    "dev-tunnel":  "https://dev.webagent.live/app",
}


# Health endpoints probed by the supervisor (readiness first, liveness fallback).
APP_URLS: dict[str, tuple[str, str]] = {
    "prod-app": ("http://localhost:8080/health/ready", "http://localhost:8080/health"),
    "dev-app":  ("http://100.112.23.15:8081/health/ready", "http://100.112.23.15:8081/health"),
}


def urls_for(spec: ServiceSpec) -> tuple[Optional[str], Optional[str]]:
    if spec.role == "tunnel":
        url = TUNNEL_URLS.get(spec.id)
        return (url, None)
    return APP_URLS[spec.id]


# ---------------------------------------------------------------------------
# Engine configuration & mutable runtime
# ---------------------------------------------------------------------------

@dataclass
class Cfg:
    startup_grace: float = 120.0    # allow an app this long to serve at boot
    unhealthy_grace: float = 45.0   # docker-unhealthy while running: restart after this
    min_attempt_gap: float = 30.0   # never auto-start/restart more often than this
    max_auto_restarts: int = 3      # recovery attempts allowed per guard window
    guard_window: float = 3600.0
    healthy_reset_after: float = 120.0  # sustained healthy time clears the crash guard
    tunnel_grace: float = 30.0         # public URL may lag while a tunnel registers


@dataclass
class Observed:
    """Real state gathered each tick (docker inspect / http probe)."""
    exists: bool = True
    running: bool = False
    docker_health: str = ""          # healthy | starting | unhealthy | ""
    started_epoch: Optional[float] = None
    http_ok: Optional[bool] = None   # apps only
    http_ms: Optional[float] = None
    http_text: str = ""              # "200", "503", "timeout", "refused"...
    netmode: str = ""               # HostConfig.NetworkMode (bridge/none/host)
    net_attached: bool = True       # has at least one docker network endpoint


@dataclass
class RT:
    """Supervisor bookkeeping for one service."""
    desired: bool = True
    crash: bool = False
    attempts: list = field(default_factory=list)   # auto recovery attempt times
    last_attempt: float = 0.0


@dataclass
class Status:
    severity: int   # 0 ok(green) 1 busy(amber) 2 bad(red) 3 off(gray)
    text: str


@dataclass
class Action:
    service: str     # service id
    kind: str        # start | stop | restart
    reason: str = ""


# ---------------------------------------------------------------------------
# Pure planning
# ---------------------------------------------------------------------------

def _attempts_allowed(rt: RT, now: float, cfg: Cfg) -> tuple[bool, str]:
    recent = [t for t in rt.attempts if now - t < cfg.guard_window]
    if len(recent) >= cfg.max_auto_restarts:
        rt.crash = True
        return False, "crash-loop guard reached - manual action required"
    if now - rt.last_attempt < cfg.min_attempt_gap:
        return False, "waiting (backoff after last attempt)"
    return True, ""


def plan(
    obs_by_id: dict[str, Observed],
    rt_by_id: dict[str, RT],
    now: float,
    cfg: Cfg,
    docker_ok: bool,
) -> tuple[list[Action], dict[str, Status], dict[str, str]]:
    """Decide what the supervisor should do this tick.

    Returns (actions, statuses, notes). Pure - no side effects.
    """
    actions: list[Action] = []
    statuses: dict[str, Status] = {}
    notes: dict[str, str] = {}

    app_specs = {s.stack: s for s in SERVICES if s.role == "app"}

    for spec in SERVICES:
        o = obs_by_id.get(spec.id, Observed())
        r = rt_by_id.setdefault(spec.id, RT())
        age = (now - o.started_epoch) if o.started_epoch is not None else None

        # --- container missing ---------------------------------------------
        if not o.exists:
            notes[spec.id] = "container does not exist"
            statuses[spec.id] = Status(2, "MISSING container")
            continue

        # --- user turned it off --------------------------------------------
        if not r.desired:
            if o.running:
                actions.append(Action(spec.id, "stop", "user stopped"))
                statuses[spec.id] = Status(3, "stopping")
            else:
                statuses[spec.id] = Status(3, "off")
            continue

        # --- docker not up yet ---------------------------------------------
        if not docker_ok:
            statuses[spec.id] = Status(1, "waiting for docker")
            continue

        # --- running but detached from its docker network ------------------
        if o.running and not o.net_attached:
            net = o.netmode or "bridge"
            if net == "default":
                net = "bridge"
            if net in ("none", "host", "container") or net.startswith("container:"):
                statuses[spec.id] = Status(2, "no network (unsupported)")
                notes[spec.id] = f"container uses netmode {net}; manual fix needed"
            else:
                allowed, why = _attempts_allowed(r, now, cfg)
                if allowed:
                    actions.append(Action(spec.id, "netconnect", f"re-attach to {net}"))
                    statuses[spec.id] = Status(2, "no network - reconnecting")
                    notes[spec.id] = "container lost its docker network"
                else:
                    statuses[spec.id] = Status(2, "no network")
                    notes[spec.id] = why
            continue

        # --- apps -----------------------------------------------------------
        if spec.role == "app":
            healthy = bool(o.http_ok)
            if o.running:
                if healthy:
                    r.crash = False
                    if age is not None and age > cfg.healthy_reset_after:
                        r.attempts = []
                    text = f"healthy {o.http_ms:.0f}ms" if o.http_ms is not None else "healthy"
                    statuses[spec.id] = Status(0, text)
                else:
                    docker_unhealthy = o.docker_health == "unhealthy"
                    over_grace = age is not None and age > cfg.startup_grace
                    over_unhealthy = docker_unhealthy and age is not None and age > cfg.unhealthy_grace
                    if over_grace or over_unhealthy:
                        allowed, why = _attempts_allowed(r, now, cfg)
                        if allowed:
                            actions.append(Action(spec.id, "restart", "unhealthy (no response)"))
                            statuses[spec.id] = Status(2, "unhealthy - restarting")
                        else:
                            statuses[spec.id] = Status(2, "unhealthy")
                            if why:
                                notes[spec.id] = why
                    elif docker_unhealthy:
                        statuses[spec.id] = Status(2, "unhealthy (docker)")
                    else:
                        statuses[spec.id] = Status(1, "starting")
                continue
            else:
                # not running, desired on
                allowed, why = _attempts_allowed(r, now, cfg)
                if allowed:
                    actions.append(Action(spec.id, "start", "desired state is on"))
                    statuses[spec.id] = Status(1, "starting")
                else:
                    statuses[spec.id] = Status(2, "stopped")
                    if why:
                        notes[spec.id] = why
                continue

        # --- tunnels --------------------------------------------------------
        app_spec = app_specs[spec.stack]
        app_obs = obs_by_id.get(app_spec.id, Observed())
        app_rt = rt_by_id.setdefault(app_spec.id, RT())
        app_healthy = bool(app_obs.http_ok) and app_rt.desired

        # an app switched off takes its tunnel down with it
        if o.running and not app_rt.desired:
            actions.append(Action(spec.id, "stop", "app turned off"))
            statuses[spec.id] = Status(3, "stopping (app off)")
            continue

        if o.running:
            if app_healthy:
                if o.http_ok is False and age is not None and age > cfg.tunnel_grace:
                    allowed, why = _attempts_allowed(r, now, cfg)
                    if allowed:
                        actions.append(Action(spec.id, "restart", "tunnel not forwarding"))
                        statuses[spec.id] = Status(2, "tunnel down - restarting")
                    else:
                        statuses[spec.id] = Status(2, "tunnel down")
                        if why:
                            notes[spec.id] = why
                else:
                    r.crash = False
                    if age is not None and age > cfg.healthy_reset_after:
                        r.attempts = []
                    if o.http_ok is False:
                        statuses[spec.id] = Status(1, "tunnel starting")
                    else:
                        statuses[spec.id] = Status(0, "running - app healthy")
            else:
                statuses[spec.id] = Status(2, "running - app not healthy")
            continue

        # tunnel not running
        if not app_rt.desired:
            statuses[spec.id] = Status(3, "off (app off)")
        elif not app_obs.exists:
            statuses[spec.id] = Status(2, "waiting for app container")
        elif not app_healthy:
            statuses[spec.id] = Status(1, "waiting for app to be healthy")
            notes[spec.id] = "starts automatically when the app answers its health check"
        else:
            allowed, why = _attempts_allowed(r, now, cfg)
            if allowed:
                actions.append(Action(spec.id, "start", "app healthy"))
                statuses[spec.id] = Status(1, "starting")
            else:
                statuses[spec.id] = Status(2, "stopped")
                if why:
                    notes[spec.id] = why

    return actions, statuses, notes
